<?php
require 'includes/functions.php';$u=auth();$error='';$editing=null;
$values=array_fill_keys(array_merge(['label'],array_keys(address_fields()),['details','map_url','latitude','longitude']),'');
$editId=(int)($_GET['edit']??0);$fromOrder=(int)($_GET['from_order']??0);
if($editId){$editing=q('SELECT * FROM user_addresses WHERE id=? AND user_id=?',[$editId,$u['id']])->fetch();if(!$editing){http_response_code(404);require 'includes/header.php';echo '<h1>ไม่พบที่อยู่</h1>';require 'includes/footer.php';exit;}$values=array_intersect_key($editing,$values);}
if($fromOrder){$source=q('SELECT * FROM orders WHERE id=? AND user_id=?',[$fromOrder,$u['id']])->fetch();if(!$source){http_response_code(404);require 'includes/header.php';echo '<h1>ไม่พบคำสั่งซื้อของคุณ</h1>';require 'includes/footer.php';exit;}$values=saved_address_from_order($source);$editing=null;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=post('action');$id=(int)post('id');
 try{
    db()->beginTransaction();address_lock_member((int)$u['id']);
    if($id&&!q('SELECT id FROM user_addresses WHERE id=? AND user_id=? FOR UPDATE',[$id,$u['id']])->fetchColumn()){http_response_code(404);throw new RuntimeException('ไม่พบที่อยู่ของคุณ');}
    if($action==='save'){
        foreach($values as $key=>$old)$values[$key]=post($key);
        if(post('confirm_save')!=='1')throw new RuntimeException('กรุณายืนยันว่าต้องการบันทึกที่อยู่นี้ในบัญชี');
        $values=validate_shipping_address($values);save_member_address((int)$u['id'],$values,isset($_POST['is_default']),$id);
    }elseif($action==='delete'&&$id){
        q('DELETE FROM user_addresses WHERE id=? AND user_id=?',[$id,$u['id']]);
        if(!q('SELECT id FROM user_addresses WHERE user_id=? AND is_default=1',[$u['id']])->fetchColumn()){$next=q('SELECT id FROM user_addresses WHERE user_id=? ORDER BY id LIMIT 1',[$u['id']])->fetchColumn();if($next)q('UPDATE user_addresses SET is_default=1 WHERE id=? AND user_id=?',[$next,$u['id']]);}
    }elseif($action==='default'&&$id){q('UPDATE user_addresses SET is_default=0 WHERE user_id=?',[$u['id']]);q('UPDATE user_addresses SET is_default=1 WHERE id=? AND user_id=?',[$id,$u['id']]);}
    else throw new RuntimeException('การดำเนินการไม่ถูกต้อง');
    db()->commit();flash($action==='delete'?'ลบที่อยู่แล้ว คำสั่งซื้อเดิมไม่เปลี่ยนแปลง':'บันทึกที่อยู่สำเร็จ');go('addresses.php');
 }catch(Throwable $exception){if(db()->inTransaction())db()->rollBack();$error=$exception instanceof PDOException?'ยังไม่สามารถบันทึกที่อยู่ได้ กรุณาลองใหม่':$exception->getMessage();}
}
$addresses=member_addresses((int)$u['id']);$oldOrders=q('SELECT id,recipient,created_at FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 20',[$u['id']])->fetchAll();require 'includes/header.php';
?>
<div class="page-heading"><h1><?=e(t('ที่อยู่ของฉัน'))?></h1><p><?=e(t('จัดการที่อยู่สำหรับครั้งต่อไป การแก้หรือลบที่นี่ไม่เปลี่ยนคำสั่งซื้อเดิม'))?></p><a href="<?=url('profile.php')?>"><?=e(t('กลับบัญชีของฉัน'))?></a></div>
<?php if($error): ?><p class="error" role="alert"><?=e(t($error))?></p><?php endif ?>
<div class="address-toolbar"><a class="button" href="<?=url('addresses.php#address-form')?>"><?=e(t('เพิ่มที่อยู่ใหม่'))?></a><a href="<?=url('checkout.php')?>"><?=e(t('ไปหน้าชำระเงิน'))?></a></div>
<?php if(!$addresses): ?><div class="notice"><?=e(t('ยังไม่มีที่อยู่ที่บันทึก ระบบจะไม่ดึงที่อยู่จากคำสั่งซื้อเก่ามาบันทึกโดยอัตโนมัติ'))?></div><?php endif ?>
<div class="address-grid"><?php foreach($addresses as $address): ?><article class="address-card"><div class="address-card-title"><h2><?=e($address['label']?:'ที่อยู่จัดส่ง')?></h2><?php if($address['is_default']): ?><span class="address-default"><?=e(t('เริ่มต้น'))?></span><?php endif ?></div><?=address_summary_html($address)?><?php if($address['map_url']): ?><p><?=delivery_location_html($address['map_url'])?></p><?php endif ?><div class="address-actions"><a href="<?=url('checkout.php?address_id='.$address['id'])?>"><?=e(t('ใช้ที่อยู่นี้'))?></a><a href="<?=url('addresses.php?edit='.$address['id'].'#address-form')?>"><?=e(t('แก้ไข'))?></a><?php if(!$address['is_default']): ?><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$address['id']?>"><button class="secondary" name="action" value="default"><?=e(t('ตั้งเป็นเริ่มต้น'))?></button></form><?php endif ?><form method="post" data-confirm="ลบที่อยู่ที่บันทึกนี้? คำสั่งซื้อเดิมจะไม่ถูกเปลี่ยน"><?=csrf()?><input type="hidden" name="id" value="<?=$address['id']?>"><button class="secondary" name="action" value="delete"><?=e(t('ลบ'))?></button></form></div></article><?php endforeach ?></div>
<section class="panel address-form-panel" id="address-form"><h2><?=$editing?'แก้ไขที่อยู่':($fromOrder?'ตรวจสอบที่อยู่จากคำสั่งซื้อเดิม':'เพิ่มที่อยู่ใหม่')?></h2><?php if($fromOrder): ?><div class="notice"><?=e(t('กรุณาตรวจสอบและเติมข้อมูลให้ครบ เลือกยืนยันแล้วกดบันทึก จึงจะเพิ่มเป็นที่อยู่ของคุณ หากคำสั่งซื้อเดิมมีเพียงพิกัด ให้เติมบ้านเลขที่ด้วย'))?></div><?php endif ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$editing?(int)$editing['id']:0?>"><label><?=e(t('ชื่อเรียกที่อยู่ (ไม่บังคับ)'))?><input name="label" maxlength="60" value="<?=e($values['label'])?>" placeholder="<?=e(t('เช่น บ้าน หรือที่ทำงาน'))?>"></label><div class="address-form-grid"><?php foreach(address_fields() as $key=>$label): ?><label><?=e(t($label))?> *<?php if($key==='address_line'): ?><textarea name="<?=$key?>" maxlength="2000" required><?=e($values[$key])?></textarea><?php else: ?><input name="<?=$key?>" type="<?=$key==='phone'?'tel':'text'?>" maxlength="<?=$key==='postcode'?5:($key==='phone'?10:120)?>" value="<?=e($values[$key])?>" required <?=$key==='postcode'?'inputmode="numeric" pattern="[0-9]{5}"':''?>><?php endif ?></label><?php endforeach ?></div><label><?=e(t('รายละเอียดเพิ่มเติม / จุดสังเกต'))?><textarea name="details" maxlength="1000"><?=e($values['details'])?></textarea></label><label><?=e(t('ลิงก์ Google Maps (ไม่บังคับ)'))?><input type="url" name="map_url" maxlength="2000" value="<?=e($values['map_url'])?>"></label><input type="hidden" name="latitude" value="<?=e($values['latitude']??'')?>"><input type="hidden" name="longitude" value="<?=e($values['longitude']??'')?>"><label class="checkbox"><input type="checkbox" name="is_default" <?=$editing&&!empty($editing['is_default'])?'checked':''?>> <?=e(t('ตั้งเป็นที่อยู่เริ่มต้น'))?></label><label class="checkbox"><input type="checkbox" name="confirm_save" value="1" required> <?=e(t('ฉันตรวจสอบและต้องการบันทึกที่อยู่นี้ในบัญชีเพื่อใช้สั่งซื้อครั้งต่อไป'))?></label><p class="payment-help"><?=e(t('ใช้ข้อมูลนี้เพื่อจัดส่งและเติมข้อมูลเมื่อสั่งซื้อ อ่าน'))?> <a href="<?=url('privacy.php')?>"><?=e(t('นโยบายความเป็นส่วนตัว'))?></a></p><button><?=e(t('บันทึกที่อยู่'))?></button></form></section>
<?php if($oldOrders): ?><section class="panel address-import"><h2><?=e(t('นำที่อยู่จากคำสั่งซื้อเดิมมาใช้'))?></h2><p><?=e(t('เลือกคำสั่งซื้อเพื่อตรวจสอบก่อน ไม่มีการบันทึกจนกว่าจะยืนยัน'))?></p><?php foreach($oldOrders as $order): ?><p><a href="<?=url('addresses.php?from_order='.$order['id'].'#address-form')?>"><?=e(t('ตรวจสอบที่อยู่ BP-'))?><?=sprintf('%06d',$order['id'])?></a> · <?=e($order['created_at'])?></p><?php endforeach ?><small><?=e(t('แสดง 20 รายการล่าสุด คำสั่งซื้ออื่นเลือกได้จากหน้ารายละเอียดในประวัติคำสั่งซื้อ'))?></small></section><?php endif ?>
<?php require 'includes/footer.php'; ?>
